#!/usr/bin/env python3
"""Bootstrap Issue #18 Version 1 end-to-end RC1 release evidence."""
from __future__ import annotations
import argparse, base64, gzip, hashlib, subprocess, sys
from pathlib import Path
EXPECTED_REPOSITORY = "Ramrattan-AI-Editorial-Studio"
EXPECTED_BRANCH = "feature/issue-018-version-1-rc1-release-readiness"
SCRIPT_PATH = "scripts/bootstrap_issue018_version_one_release_readiness.py"
SENTINEL = "ISSUE_018_VERSION_ONE_RELEASE_READINESS_COMPLETE"
_BLOBS = {
    'CHANGELOG.md': '',
    'ROADMAP.md': '',
    'docs/Release_Checklist.md': '',
    'docs/VERSION_ONE_SCORECARD.md': '',
    'docs/product/Current_Product_Focus.md': '',
    'docs/product/Release_v1.0.md': '',
    'docs/demos/Version-1-End-to-End-Demo.md': '',
    'tests/test_capability011_documentation.py': '',
    'tests/test_rc1_checkpoint.py': '',
    'tests/test_version_one_end_to_end.py': '',
}
FILES = {p: gzip.decompress(base64.b64decode(v)).decode("utf-8") for p, v in _BLOBS.items()}
class BootstrapError(RuntimeError): pass
def run(command, root, capture=False):
    result=subprocess.run(command,cwd=root,text=True,capture_output=capture,check=False)
    if result.returncode: raise BootstrapError(" ".join(command)+": "+(result.stderr or result.stdout or "command failed").strip())
    return result.stdout if capture else ""
def repository_root():
    root=Path(__file__).resolve().parents[1]
    if root.name != EXPECTED_REPOSITORY or not (root/".git").exists(): raise BootstrapError("Run from the expected repository.")
    return root
def changed_paths(root):
    return {line[3:].split(" -> ")[-1] for line in run(["git","status","--porcelain=v1","--untracked-files=all"],root,True).splitlines()}
def verify(root):
    branch=run(["git","branch","--show-current"],root,True).strip()
    if branch != EXPECTED_BRANCH: raise BootstrapError(f"Expected {EXPECTED_BRANCH}; found {branch}.")
    unexpected=changed_paths(root)-{*FILES,SCRIPT_PATH,"scripts/bootstrap_capability011_portable_editorial_project.py"}
    if unexpected: raise BootstrapError("Unexpected working-tree paths: "+", ".join(sorted(unexpected)))
def preview(root):
    verify(root); print("Issue #18 Version 1 release-readiness preview - no files changed.")
    for relative in sorted(FILES): print(f"- {relative}")
def apply(root):
    before=hashlib.sha256((root/SCRIPT_PATH).read_bytes()).hexdigest()
    for relative,content in FILES.items():
        path=root/relative; path.parent.mkdir(parents=True,exist_ok=True)
        if not path.is_file() or path.read_text(encoding="utf-8") != content: path.write_text(content,encoding="utf-8")
    if hashlib.sha256((root/SCRIPT_PATH).read_bytes()).hexdigest() != before: raise BootstrapError("Bootstrap modified itself during apply.")
def validate_generated(root):
    mismatches=[p for p,e in FILES.items() if not (root/p).is_file() or (root/p).read_text(encoding="utf-8") != e]
    if mismatches: raise BootstrapError("Generated content mismatch: "+", ".join(sorted(mismatches)))
def main():
    parser=argparse.ArgumentParser(); parser.add_argument("--apply",action="store_true"); args=parser.parse_args(); root=repository_root()
    if args.apply: verify(root); apply(root); validate_generated(root); print(SENTINEL)
    else: preview(root)
    return 0
if __name__ == "__main__":
    try: raise SystemExit(main())
    except BootstrapError as exc: print(f"Issue #18 bootstrap stopped: {exc}",file=sys.stderr); raise SystemExit(1)
